from dataclasses import dataclass
from typing import Callable, Generator, Generic, Iterable, TypeVar
from xml.etree.ElementTree import Element

from .tags import HTMLTagDefinition, tag_definition

P = TypeVar("P")


@dataclass
class HTMLTag(Generic[P]):
    definition: HTMLTagDefinition
    attributes: list[tuple[str, str]]
    children: list["str | P | HTMLTag[P]"]


def flatten(children: Iterable[str | P | HTMLTag[P]]) -> Generator[str | P, None, None]:
    for child in children:
        if isinstance(child, HTMLTag):
            yield from flatten(child.children)
        else:
            yield child


def decode(
    root: Element, decode_payload: Callable[[Element], P]
) -> list[str | P | HTMLTag[P]]:
    children: list[str | P | HTMLTag[P]] = []
    if root.text:
        children.append(root.text)

    for child in root:
        tag_def = tag_definition(child.tag)
        if tag_def is not None:
            attributes = list(child.attrib.items())
            children.append(
                HTMLTag(
                    definition=tag_def,
                    attributes=attributes,
                    children=decode(child, decode_payload),
                )
            )
        else:
            children.append(decode_payload(child))

        if child.tail:
            children.append(child.tail)

    return children


def encode(
    root: Element,
    children: list[str | P | HTMLTag[P]],
    encode_payload: Callable[[P], Element],
) -> None:
    if not children:
        return

    last_element: Element | None = None
    for child in children:
        if isinstance(child, str):
            if last_element is None:
                root.text = (root.text or "") + child
            else:
                last_element.tail = (last_element.tail or "") + child
        elif isinstance(child, HTMLTag):
            element = Element(child.definition.name, dict(child.attributes))
            encode(element, child.children, encode_payload)
            root.append(element)
            last_element = element
        else:
            element = encode_payload(child)
            root.append(element)
            last_element = element

def _normalize_paragraph_content(paragraph: ParagraphLayout):
    if len(paragraph.blocks) < 2:
        return

    for i in range(1, len(paragraph.blocks)):
        block1 = paragraph.blocks[i - 1]
        block2 = paragraph.blocks[i]

        text1 = last(block1.content)
        text2 = first(block2.content)
        if not isinstance(text1, str) or not isinstance(text2, str):
            continue

        text1 = text1.rstrip()
        text2 = text2.lstrip()
        if not _is_splitted_word(text1, text2):
            continue

        tail_end = 0
        for j in range(len(text2)):
            if is_latin_letter(text2[j]):
                tail_end = j + 1
            else:
                break

        block1.content[-1] = text1[:-1] + text2[:tail_end]
        block2.content[0] = text2[tail_end:].lstrip()
        if not block2.content[0]:
            del block2.content[0]

    # 极端情况下 block2 会因为单词被移走而被清空。此时要将其整个删去。
    paragraph.blocks = [block for block in paragraph.blocks if block.content]


def _parse_block_content(text: str | None) -> Content:
    if not text:
        return []

    protected_text, expressions, placeholder_pattern = _protect_latex_expressions(text)
    root_content: Content = parse_raw_markdown(protected_text)

    def expand_text(text: str):
        pos = 0
        for match in placeholder_pattern.finditer(text):
            if match.start() > pos:
                yield text[pos : match.start()]
            expression = expressions[int(match.group(1))]
            yield InlineExpression(
                kind=expression.kind,
                content=expression.content,
            )
            pos = match.end()
        if pos < len(text):
            yield text[pos:]

    expand_text_in_content(
        content=root_content,
        expand=expand_text,
    )
    return root_content


def _protect_latex_expressions(text: str) -> tuple[str, list[ParsedItem], re.Pattern]:
    expressions: list[ParsedItem] = []
    parts: list[str] = []
    placeholder_prefix = _create_latex_placeholder_prefix(text)

    for item in parse_latex_expressions(text):
        if item.kind == ExpressionKind.TEXT:
            parts.append(item.content)
            continue

        parts.append(f"{placeholder_prefix}{len(expressions)}\uE001")
        expressions.append(item)

    placeholder_pattern = re.compile(f"{re.escape(placeholder_prefix)}(\\d+)\uE001")
    return "".join(parts), expressions, placeholder_pattern


